(()=>{'use strict';const root=document.getElementById('bonga-execute-matrix');if(!root)return;const tiers={1:['Digital Visibility','Investigate your business visibility and manage evidence-backed opportunities.','#evidence','Open visibility workspace →'],2:['Creative Studio','Open the existing Bonga Bhengu Digital Studio for media projects and production.','#digital-studio','Open creative studio →'],3:['Content Automation','Prepare and review social campaigns. Publishing requires an authorized platform connection.','#social-campaigns','Open campaign drafts →']};const out=document.getElementById('bonga-tier-content');root.querySelectorAll('[data-bonga-tier]').forEach(btn=>btn.addEventListener('click',()=>{const item=tiers[btn.dataset.bongaTier];root.querySelectorAll('[data-bonga-tier]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));out.replaceChildren();const h=document.createElement('h2');h.textContent=item[0];const p=document.createElement('p');p.textContent=item[1];const a=document.createElement('a');a.href=item[2];a.textContent=item[3];out.append(h,p,a)}));document.getElementById('bonga-rental-action').addEventListener('click',()=>{const name=document.getElementById('bonga-rental-name').value.trim(),business=document.getElementById('bonga-rental-business').value.trim(),status=document.getElementById('bonga-rental-status');if(!name||!business){status.textContent='Enter your name and business or collection first.';return}const message='Bonga Bhengu digital space rental enquiry\nName: '+name+'\nBusiness: '+business+'\nPlease send me availability and terms.';const a=document.createElement('a');a.href='mailto:donlegendwear@gmail.com?subject='+encodeURIComponent('Bonga Bhengu rental enquiry')+'&body='+encodeURIComponent(message);a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open email to send enquiry →';status.replaceChildren(document.createTextNode('Your enquiry is ready. Send it through your email app to submit. '),a);})})();